From 2c4e02462e9933a9d6cc358ada615cfef5c55b4d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:51:50 +0100
Subject: [PATCH] applets/pager: switch to the next desktop on the activation
 shortcut

The pager has no default click action, so the keyboard shortcut set in
its settings did nothing visible. Now activating the widget switches to
the next desktop, cycling back to the first one after the last.

BUG: 439707
---
 applets/pager/qml/main.qml | 10 ++++++++++
 1 file changed, 10 insertions(+)

diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..99a52c2616 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -170,6 +170,16 @@ PlasmoidItem {
         }
     }

+    Connections {
+        target: Plasmoid
+
+        function onActivated() {
+            if (repeater.count > 1) {
+                pagerModel.changePage((pagerModel.currentPage + 1) % repeater.count);
+            }
+        }
+    }
+
     Component {
         id: desktopLabelComponent

